const items = $input.all();
const results = [];

for (const item of items) {
  // Récupère le XML (soit binary, soit json string)
  let xml = '';
  if (item.binary?.data?.data) {
    xml = Buffer.from(item.binary.data.data, 'base64').toString();
  } else if (typeof item.json === 'string') {
    xml = item.json;
  } else {
    xml = JSON.stringify(item.json);
  }

  // Regex plus permissive pour capturer les items
  const itemRegex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
  const items = xml.match(itemRegex);

  if (items && items.length > 0) {
    for (let i = 0; i < Math.min(items.length, 10); i++) {
      const itemXml = items[i];

      // Extraction simple
      const titleMatch = itemXml.match(/<title>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/title>/s);
      const linkMatch = itemXml.match(/<link>([^<]*)<\/link>/s);
      const pubDateMatch = itemXml.match(/<pubDate>([^<]*)<\/pubDate>/s);
      const descMatch = itemXml.match(/<description>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?<\/description>/s);

      const title = titleMatch ? titleMatch[1].trim() : '';
      const link = linkMatch ? linkMatch[1].trim() : '';
      const pubDate = pubDateMatch ? pubDateMatch[1].trim() : '';
      const description = descMatch ? descMatch[1].replace(/<[^>]*>/g, '').trim().substring(0, 500) : '';

      if (title && link) {
        results.push({
          json: {
            title,
            link,
            description,
            pubDate,
            source: 'Google News'
          }
        });
      }
    }
  }
}

return results;

