const items = $input.all();
const results = [];

for (const item of items) {
  try {
    // Récupère la réponse de Browserless
    let data = item.json.data || item.json;

    // Si c'est un array, prend le premier élément
    if (Array.isArray(data)) {
      data = data[0];
    }

    // Extrait le HTML brut
    let html = '';
    if (data.results && Array.isArray(data.results)) {
      html = data.results.map(r => r.html || r.text || '').join('\n');
    } else if (data.html) {
      html = data.html;
    } else if (data.text) {
      html = data.text;
    } else {
      html = JSON.stringify(data);
    }

    // Nettoyage HTML
    let text = html
      // Supprime scripts et styles
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
      // Supprime commentaires HTML
      .replace(/<!--[\s\S]*?-->/g, '')
      // Remplace les balises par des espaces/sauts
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/p>/gi, '\n\n')
      .replace(/<\/div>/gi, '\n')
      .replace(/<\/h[1-6]>/gi, '\n\n')
      .replace(/<li>/gi, '• ')
      .replace(/<\/li>/gi, '\n')
      // Supprime toutes les balises restantes
      .replace(/<[^>]+>/g, ' ')
      // Décode les entités HTML
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&eacute;/g, 'é')
      .replace(/&egrave;/g, 'è')
      .replace(/&agrave;/g, 'à')
      .replace(/&ccedil;/g, 'ç')
      // Nettoie les espaces multiples
      .replace(/\s+/g, ' ')
      .replace(/\n\s+/g, '\n')
      .replace(/\n{3,}/g, '\n\n')
      .trim();

    // Limite la taille (premiers 3000 caractères)
    const contenu = text.substring(0, 3000);

    // Extrait un titre si possible (première ligne non vide)
    const lignes = contenu.split('\n').filter(l => l.trim().length > 0);
    const titre = lignes[0]?.substring(0, 200) || '';

    results.push({
      json: {
        titre_scrape: titre,
        contenu_nettoye: contenu,
        longueur: contenu.length,
        titre_original: item.json.title || '',
        link: item.json.link || '',
        source: item.json.source || ''
      }
    });

  } catch (e) {
    // En cas d'erreur, retourne les données originales
    results.push({
      json: {
        titre_scrape: '',
        contenu_nettoye: '',
        longueur: 0,
        titre_original: item.json.title || '',
        link: item.json.link || '',
        source: item.json.source || '',
        erreur: e.message
      }
    });
  }
}

return results;
